    if not (en <= ein[4]):
      block L460:
        fdo j, 2, nvib2:
          if en <= xvib2[j]: break L460
        j = nvib2
      a = (yvib2[j] - yvib2[j - 1]) / (xvib2[j] - xvib2[j - 1])
      b = (xvib2[j - 1] * yvib2[j] - xvib2[j] * yvib2[j - 1]) / (xvib2[j - 1] - xvib2[j])
      qin[4, i] = a * en + b
      qin[4, i] = qin[4, i] / (1.0 + apopv1) * 1e-16
    # SUPERELASTIC VIBRATION HARMONIC 2V2 BENDING MODE
    qin[5, i] = 0.0
    if not (en == 0.0):
      block L520:
        fdo j, 2, nvib3:
          if en + ein[6] <= xvib3[j]: break L520
        j = nvib3
      a = (yvib3[j] - yvib3[j - 1]) / (xvib3[j] - xvib3[j - 1])
      b = (xvib3[j - 1] * yvib3[j] - xvib3[j] * yvib3[j - 1]) / (xvib3[j - 1] - xvib3[j])
      qin[5, i] = (en + ein[6]) * (a * (en + ein[6]) + b) / en
      qin[5, i] = qin[5, i] * apop2v2 / (1.0 + apop2v2) * 1e-16
    # VIBRATION HARMONIC 2V2 BENDING MODE
    qin[6, i] = 0.0
    if not (en <= ein[6]):
      block L560:
        fdo j, 2, nvib3:
          if en <= xvib3[j]: break L560
        j = nvib3
      a = (yvib3[j] - yvib3[j - 1]) / (xvib3[j] - xvib3[j - 1])
      b = (xvib3[j - 1] * yvib3[j] - xvib3[j] * yvib3[j - 1]) / (xvib3[j - 1] - xvib3[j])
      qin[6, i] = a * en + b
      qin[6, i] = qin[6, i] / (1.0 + apop2v2) * 1e-16
    # VIBRATION V3 ASYMMETRIC STRETCH
    qin[7, i] = 0.0
    if not (en <= ein[7]):
      block L620:
        fdo j, 2, nvib4:
          if en <= xvib4[j]: break L620
        j = nvib4
      a = (yvib4[j] - yvib4[j - 1]) / (xvib4[j] - xvib4[j - 1])
      b = (xvib4[j - 1] * yvib4[j] - xvib4[j] * yvib4[j - 1]) / (xvib4[j - 1] - xvib4[j])
      efac = sqrt(1.0 - ein[7] / en)
      qin[7, i] = 0.6389999985694885 * ln((1.0 + efac) / (1.0 - efac)) / en
      qin[7, i] = (qin[7, i] + (a * en + b)) * 1e-16
    # SUM OF HARMONICS NV1
    qin[8, i] = 0.0
    if not (en <= ein[8]):
      block L720:
        fdo j, 2, nvib5:
          if en <= xvib5[j]: break L720
        j = nvib5
      a = (yvib5[j] - yvib5[j - 1]) / (xvib5[j] - xvib5[j - 1])
      b = (xvib5[j - 1] * yvib5[j] - xvib5[j] * yvib5[j - 1]) / (xvib5[j - 1] - xvib5[j])
      qin[8, i] = (a * en + b) * 1e-16
    # SUM OF HIGHER HARMONICS (0.512)
    qin[9, i] = 0.0
    if not (en <= ein[9]):
      block L760:
        fdo j, 2, nvib6:
          if en <= xvib6[j]: break L760
        j = nvib6
      a = (yvib6[j] - yvib6[j - 1]) / (xvib6[j] - xvib6[j - 1])
      b = (xvib6[j - 1] * yvib6[j] - xvib6[j] * yvib6[j - 1]) / (xvib6[j - 1] - xvib6[j])
      qin[9, i] = (a * en + b) * 1e-16
    # EXCITATION (DISOCIATION)
    qin[10, i] = 0.0
    if not (en <= ein[10]):
      block L820:
        fdo j, 2, nexc:
          if en <= xexc[j]: break L820
        j = nexc
      a = (yexc[j] - yexc[j - 1]) / (xexc[j] - xexc[j - 1])
      b = (xexc[j - 1] * yexc[j] - xexc[j] * yexc[j - 1]) / (xexc[j - 1] - xexc[j])
      qin[10, i] = (a * en + b) * 1e-16
    q[1, i] = q[2, i] + q[3, i] + q[4, i] + qin[1, i] + qin[2, i] + qin[3, i] + qin[4, i] + qin[5, i] + qin[6, i] + qin[7, i] + qin[8, i] + qin[9, i] + qin[10, i]
  # SAVE COMPUTE TIME
  if inpt.efinal <= ein[10]: nin = 9
  if inpt.efinal <= ein[9]: nin = 8
  if inpt.efinal <= ein[8]: nin = 7
  if inpt.efinal <= ein[7]: nin = 6
  return
